import{z as A,x as i,o as E,c as L,q as r,j as o,D as e,d as B,s as n,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"GLM 与 ChatGLM","description":"","frontmatter":{"title":"GLM 与 ChatGLM","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/glm.md","filePath":"llm/glm.md","lastUpdated":1791413859000}'),G={name:"llm/glm.md"};function h(M,a,p,m,C,d){const l=i("Mermaid");return E(),L("div",null,[a[2]||(a[2]=r('<h1 id="glm-与-chatglm" tabindex="-1">GLM 与 ChatGLM <a class="header-anchor" href="#glm-与-chatglm" aria-label="Permalink to &quot;GLM 与 ChatGLM&quot;">​</a></h1><div class="epigraph"><p>我们提出基于自回归空白填充的通用语言模型 GLM：随机挖掉连续片段，再按自回归方式依次填回。</p><footer>—— Du 等，GLM: General Language Model Pretraining with Autoregressive Blank Infilling，ACL 2022</footer></div><p>在 BERT 式掩码与 GPT 式从左到右之间，清华 GLM 选了一条中间路：<strong>自回归空白填充</strong>。随机把连续 span 挖成空白，模型按某种顺序把空白写回来，既保留双向可见的「完形填空」信号，又保留生成时的因果解码。2022 年的 GLM-130B 把这套目标做到双语千亿密集模型；2023 年智谱与清华把对齐后的对话模型做成 ChatGLM，并开源 ChatGLM-6B，成为中文侧可本地部署的对话基线。本篇写从空白填充到对话产品的这条线；GLM-4 起的工具与长窗是 <a href="/llm/glm-4">下一篇</a> 的主题，这里只作世代边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预训练框架一度三分天下。自编码（BERT）擅长 NLU，但不自然地生成长文本。自回归（GPT）擅长续写，完形与分类要改成别扭的 prompt。编码器–解码器（T5）用空白填充分统一成 text-to-text，但空白之间的顺序与位置编码仍有设计空间。Du 等人要的是<strong>一个预训练目标</strong>覆盖 NLU、条件生成与无条件生成：通过改变空白的个数与长度来切换任务类型，而不是换模型族。</p><p><span class="marginnote">自回归空白填充，说白了就是「先挖洞、再按顺序把洞填回来」：输入侧句子除了洞都完整可见（练双向理解），输出侧像写作文一样逐字把洞补上（练因果生成）。一个训练目标同时给两种信号，是 GLM 整个家族故事的起点。</span></p><p>对话则是另一层问题。千亿双向或空白填充模型不能直接当聊天机器人：需要指令数据、人类反馈，以及能在消费级显卡上跑的小模型。ChatGLM 把 GLM 算法得到的双语能力，收成「中英问答助手」，并用量化把 6.2B 塞进约 6GB 显存的 INT4 场景。这是目标函数之后的产品化，不是新发明一种注意力。</p><h3 id="空白填充不是-bert-的独立分类头" tabindex="-1">空白填充不是 BERT 的独立分类头 <a class="header-anchor" href="#空白填充不是-bert-的独立分类头" aria-label="Permalink to &quot;空白填充不是 BERT 的独立分类头&quot;">​</a></h3><p>BERT 在 <code>[MASK]</code> 上做词表 softmax，多 token 答案要迭代或限制成单字。GLM 把每个空白当成一段要生成的 token 序列，用自回归写完再处理下一个空白。因此完形可以是短语或句子。NLU 被改写成人工模板下的挖空（PET 一类），多 token 答案成为合法。这是 GLM 相对 BERT 的机制差，也是它后来能接对话 SFT 的原因——对话本来就是条件生成。</p><p><span class="marginnote">论文还强调 2D 位置编码与 span 乱序：一个维度标原句位置，一个维度标空白内解码位置；预测空白的顺序可打乱。这是相对 T5 空白填充的改进点，写实现时不要当成「就是 T5」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="glm-目标" tabindex="-1">GLM 目标 <a class="header-anchor" href="#glm-目标" aria-label="Permalink to &quot;GLM 目标&quot;">​</a></h3><p>从文档中挖连续片段，输入侧留下带空白标记的上下文（可见两侧，故有双向信号），输出侧按自回归重建被挖内容：</p> \\[p(s_1,\\ldots,s_m\\mid x_{\\backslash s})=\\prod_{j=1}^{m}\\prod_{t}p\\bigl(s_{j,t}\\mid x_{\\backslash s}, s_{\\lt j}, s_{j,\\lt t}\\bigr). \\]<p>\\(m\\) 与 \\(|s_j|\\) 可变：短而密的空白偏 NLU；少而长的空白偏生成。多任务混合使单一预训练权重能微调到两类下游。模型是 Transformer，具体层规范随年代变：早期 GLM 与 BERT 更近，ChatGLM2 起逐步靠拢 GPT 式 RMSNorm、旋转位置等，但家族叙事仍把预训练目标溯源到 2022 这篇 ACL。</p><h3 id="glm-130b-把目标推到双语-130b" tabindex="-1">GLM-130B：把目标推到双语 130B <a class="header-anchor" href="#glm-130b-把目标推到双语-130b" aria-label="Permalink to &quot;GLM-130B：把目标推到双语 130B&quot;">​</a></h3><p>Zeng 等（arXiv:2210.02414，ICLR 2023）发布 <strong>GLM-130B</strong>：英文+中文，约 400B token 量级的公开叙述（中英各约 200B），设计目标包括单机 8×A100-40G 可推、INT4 后可在更小设备上评估。它仍是 GLM 算法上的密集双向/空白填充预训练模型，不是对话对齐后的 Chat 权重。开源的是基座与训练日志、量化经验，用来证明「百亿–千亿双语」可复现，而不是提供 chatbot API。</p><h3 id="chatglm-对齐成对话" tabindex="-1">ChatGLM：对齐成对话 <a class="header-anchor" href="#chatglm-对齐成对话" aria-label="Permalink to &quot;ChatGLM：对齐成对话&quot;">​</a></h3><p>2023 年 3 月前后，对齐后的 ChatGLM 上线，开源 <strong>ChatGLM-6B</strong>（62 亿参数）：约 1T 级中英语料训练叙述，再加 SFT、反馈自助与 RLHF，针对中文问答与对话。量化后可在消费卡本地跑。随后 <strong>ChatGLM2-6B</strong>：混合 GLM 目标、更长上下文（对话对齐 8K、可到 32K）、多查询注意力、官方实现约 42% 加速。<strong>ChatGLM3-6B</strong> 进一步把工具调用、更完整的 Base 与对话分层写入开源栈。家族综述（Team GLM，arXiv:2406.12793）把这条线接到 GLM-4；那一代的 All Tools 与 128K 不在本篇展开。</p><p><span class="marginnote">数字实例：6.2B 参数若按 FP16 存放约要 12.4 GB 显存；INT4 量化后权重只占 3 GB 出头，加上运行开销约 6 GB——正好塞进一张消费级显卡。ChatGLM-6B 当年「笔记本可跑」的名声，一半来自模型小，一半来自这份量化账。</span></p>',20)),(E(),o(s,null,{default:e(()=>[n(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E7%A9%BA%E7%99%BD%E5%A1%AB%E5%85%85%20ACL'22%22%5D%20--%3E%20P130%5B%22GLM-130B%20%E5%8F%8C%E8%AF%AD%E5%9F%BA%E5%BA%A7%22%5D%0A%20%20OBJ%20--%3E%20S6%5B%22%E8%A7%84%E6%A8%A1%E7%BC%A9%E5%B0%8F%E7%9A%84%E5%8F%8C%E8%AF%AD%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20P130%20--%3E%20AL%5B%22SFT%20%2F%20%E4%BA%BA%E7%B1%BB%E5%8F%8D%E9%A6%88%22%5D%0A%20%20S6%20--%3E%20AL%0A%20%20AL%20--%3E%20C1%5B%22ChatGLM-6B%20%E5%AF%B9%E8%AF%9D%22%5D%0A%20%20C1%20--%3E%20C2%5B%22ChatGLM2%2F3%20%E9%95%BF%E7%AA%97%E4%B8%8E%E5%B7%A5%E5%85%B7%E9%9B%8F%E5%BD%A2%22%5D%0A%20%20C2%20--%3E%20C4%5B%22GLM-4%20%E4%B8%96%E4%BB%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"ChatGLM 是清华 KE 实验室与智谱（Zhipu）共同产品线上的名称。引用时论文作者与公司博客可能并列；权重许可以当时仓库为准，不能默认 Apache 可商用。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"空白填充让同一个解码器既看见空洞两侧（理解），又必须按顺序发射 token（生成）。对话 SFT 把「空洞」特化成「用户已说完，助手空白在后」：条件是聊天前缀，生成是助手轮，双向信号退化成因果对话，这是目标上的特化而不是换骨架。因此 ChatGLM 能从 GLM 继承中文填空与生成，而不必先训一个纯 GPT 再另训 BERT。",-1)),(E(),o(s,null,{default:e(()=>[n(l,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E4%B8%89%E7%A7%8D%E4%B8%BB%E6%B5%81%E9%A2%84%E8%AE%AD%E7%BB%83%E7%9B%AE%E6%A0%87%E5%AF%B9%E6%AF%94%22%5D%20--%3E%20BERT%5B%22BERT%EF%BC%9A%E9%9A%8F%E6%9C%BA%E7%9B%96%E4%BD%8F%E5%8D%95%20token%EF%BC%8C%E5%90%84%E8%87%AA%E7%8B%AC%E7%AB%8B%E7%8C%9C%22%5D%0A%20%20SUB%20--%3E%20GPT%5B%22GPT%EF%BC%9A%E5%8F%AA%E8%83%BD%E7%9C%8B%E5%B7%A6%E8%BE%B9%EF%BC%8C%E9%80%90%E5%AD%97%E7%BB%AD%E5%86%99%22%5D%0A%20%20SUB%20--%3E%20GLM%5B%22GLM%EF%BC%9A%E6%8C%96%E8%BF%9E%E7%BB%AD%20span%EF%BC%8C%E5%8F%8C%E5%90%91%E7%9C%8B%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20BERT%20--%3E%20N1%5B%22%E7%90%86%E8%A7%A3%E5%BC%BA%EF%BC%8C%E7%94%9F%E6%88%90%E5%88%AB%E6%89%AD%22%5D%0A%20%20GPT%20--%3E%20N2%5B%22%E7%94%9F%E6%88%90%E5%BC%BA%EF%BC%8C%E5%AE%8C%E5%BD%A2%E8%A6%81%E6%94%B9%20prompt%22%5D%0A%20%20GLM%20--%3E%20N3%5B%22%E7%A9%BA%E7%99%BD%E7%9F%AD%E8%80%8C%E5%A4%9A%20%E2%86%92%20%E5%81%8F%E7%90%86%E8%A7%A3%22%5D%0A%20%20GLM%20--%3E%20N4%5B%22%E7%A9%BA%E7%99%BD%E9%95%BF%E8%80%8C%E5%B0%91%20%E2%86%92%20%E5%81%8F%E7%94%9F%E6%88%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>130B 与 6B 的差别是容量与对齐深度。6B 能在笔记本上跑，世界知识与复杂推理明显更窄，靠的是中文对话数据的密度。2 代引入 MQA 与更长窗，是在 GLM 目标之外叠上解码器 LM 已经标准化的工程：KV 变小、RoPE 类位置、更稳的 Norm。到这一步，ChatGLM 在实现上已非常接近「双语 Llama 式对话模型」，但训练故事仍从空白填充讲起——评测上要用对话基准，而不是 SuperGLUE 填空，才能反映产品能力。</p><p>从填充到对话的失败模式也在变。填充会在空洞里写一个局部合法、全局矛盾的 span；对话会顺从用户的错误前提。RLHF 压低有害输出，也会提高拒答与「套话」。6B 量化后的数值噪声在长中文生成上更明显，这是部署问题，不是 GLM 目标的理论缺陷。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>早期 ChatGLM-6B 上下文短（2K 量级叙事）、英文弱于中文、有时重复。不能把它的 2023 年体验写成 2024 年 GLM-4 的能力。GLM-130B 的双向/空白填充推理图与因果 Chat 不同，不能把 130B 基座直接当 ChatGLM 用。家族综述里的 MMLU 跃迁（报告中的世代对照）混了数据、对齐与架构，不能归因成「空白填充天生比 GPT 高 40 分」。</p><p><span class="marginnote">常见误区：初学者容易以为开源的 GLM-130B 就是一个能聊天的模型。实际上它是对齐之前的「基座」——擅长填空与续写，不会按对话格式回答；要聊天得等 ChatGLM 那一步的指令微调与人类反馈。基座与 Chat 权重是两个东西，下载和评测时都别混。</span></p><p>本篇不讨论 GLM-4 的 128K、All Tools、9B 开源细节。需要那些规格时读 glm-4 篇与 arXiv:2406.12793 的对应章节。写 2022 目标时引用 ACL 论文即可，不必给 ChatGLM-6B 编造单独的 arXiv 号——6B 以仓库与博客为出处。</p><p><span class="marginnote">「GLM」三字母后来也出现在图像与多模态型号名里。本文仅指语言模型这条：General Language Model → ChatGLM。视觉 GLM 不是空白填充论文的推论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GLM（Du 等，ACL 2022）用自回归空白填充统一 NLU 与生成，辅以 2D 位置与 span 乱序。</li><li>GLM-130B（Zeng 等，ICLR 2023）是该目标上的开源双语 130B 基座，不是聊天模型。</li><li>ChatGLM 把 GLM 能力对齐成中英对话；ChatGLM-6B 可本地量化部署，2/3 代补长窗、MQA 与工具雏形。</li><li>对话 SFT 把「填空白」特化成「填助手轮」，实现上逐渐靠近因果 LM 工程惯例。</li><li>出处：Du 等，<em>GLM: General Language Model Pretraining with Autoregressive Blank Infilling</em>，ACL 2022（arXiv:2103.10360）；Zeng 等，<em>GLM-130B</em>，arXiv:2210.02414；Team GLM，<em>ChatGLM: A Family of Large Language Models from GLM-130B to GLM-4 All Tools</em>，arXiv:2406.12793；ChatGLM-6B/2/3 开源仓库与同期智谱博客。</li></ul>',9))])}const D=A(G,[["render",h]]);export{T as __pageData,D as default};
